mapper.select:
SELECT  id, api_code, request_no, batch_no, scene, `data`, `status`, msg, create_time, update_time,down_status,is_del
FROM b_marketing_tcyr_sync_record
WHERE api_code = #{apiCode}
  AND status = #{status}
  AND is_del = 1

SELECT  id, api_code, request_no, batch_no, scene, `data`, `status`, msg, create_time, update_time,down_status,is_del
FROM b_marketing_tcyr_sync_record
WHERE api_code = #{apiCode}
  AND status = #{status}
  AND down_status = 0
  AND is_del = 1

SELECT COUNT(1)
FROM b_marketing_tcyr_sync_record
WHERE api_code = #{apiCode}
  AND (
    batch_no = #{batchPrefix}
    OR batch_no LIKE CONCAT(#{batchPrefix}, '\_%')
  )
  AND DATE(create_time) = CURRENT_DATE()
  AND is_del = 1

SELECT  MAX(id)
FROM b_marketing_sync_${apiCode}
WHERE cust_num IN

    #{userKey}

GROUP BY cust_num;

SELECT cust_num AS custNum, cell_md5 AS cell FROM ( SELECT cust_num, cell_md5, ROW_NUMBER() OVER (PARTITION BY cust_num ORDER BY applet_time DESC) AS rn FROM b_marketing_sync_${apiCode} WHERE status = 1 AND cust_num IN
#{userKey}
) t WHERE rn = 1
